import{_ as r,h as l,i as t,c as i,v as e,p as s,x as n,m,e as d,S as p}from"./chunks/framework.Dvtg8yj2.js";const B=JSON.parse('{"title":"Landmark Attention","description":"","frontmatter":{"title":"Landmark Attention","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/landmark-attention.md","filePath":"llm/landmark-attention.md","lastUpdated":1788454257000}'),h={name:"llm/landmark-attention.md"};function k(A,a,E,c,f,_){const o=l("Mermaid");return t(),i("div",null,[a[1]||(a[1]=e('<h1 id="landmark-attention" tabindex="-1">Landmark Attention <a class="header-anchor" href="#landmark-attention" aria-label="Permalink to &quot;Landmark Attention&quot;">​</a></h1><div class="epigraph"><p>不必让每个查询扫完整段历史；先问每一块的地标，再只对选中的块做随机访问，上下文长度就可以从二次扫描里解开。</p><footer>—— Amirkeivan Mohtashami, Martin Jaggi, Landmark Attention, 2023</footer></div><p>全注意力把过去每一个键都放进可见集，长度一涨，<a href="/llm/attention-quadratic-cost">二次代价</a>与 KV 体积一起涨。滑窗把远键整段剪掉；压缩记忆把远历史揉进固定状态，细节对不准。Mohtashami 与 Jaggi 2023 年的 Landmark Attention 走第三条路：把序列切成块，每块选出一个地标 token，查询先对地标做一次粗检索，再只对命中块里的原始 token 做细注意力。于是「任意远的某段」可以按内容跳进去，而不必常驻全部键。本篇只讲这条地标随机访问，KV 预算的其他压法见 <a href="/llm/kv-as-long-context">KV 压缩作为长上下文手段</a>，按块可学习选择见 <a href="/llm/native-sparse-attention">Native Sparse Attention</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>长上下文要同时满足两件事：查询必须能对准很早以前的某一个字面量；计算与缓存又不能随 \\(n\\) 二次膨胀。固定稀疏图给不出内容相关的远边；层叠滑窗的感受野是有损接力，针测会失败。若把整段 KV 都留下，decode 显存先爆。需要一种训练得出来的块级目录：目录项很少，但每一项都能把查询带回那一块的原始键。</p><p>地标机制的问题设定因此是：块内信息由谁代表、查询如何用代表做随机访问、训练时的可见集如何与推理时的「先地标、后局部」对齐。做不到对齐，上线一改图就会掉点；代表若不可学习，目录就是平均池化，精确拷贝仍然失败。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="按块插入地标" tabindex="-1">按块插入地标 <a class="header-anchor" href="#按块插入地标" aria-label="Permalink to &quot;按块插入地标&quot;">​</a></h3><p>输入按固定块长 \\(\\ell\\) 切开，每块末尾插入一个地标 token。地标不是事后池化出来的摘要向量，而是序列里的真实位置，参与同一套注意力与前馈。训练时，块内普通 token 主要看见本块邻居；地标则看见本块全部 token，从而被梯度逼着成为该块的可寻址代表。后续位置若不能直接扫过往全部键，就只能先碰到这些地标——目录是训出来的，不是外挂检索器。</p><p><span class="marginnote">地标是序列中的一个 token，不是块均值。均值对所有查询都相同；地标的键随查询进入注意力，不同问题会点亮不同块。这是它和不可学习压缩记忆的差别。</span></p><h3 id="先对地标、再对局部" tabindex="-1">先对地标、再对局部 <a class="header-anchor" href="#先对地标、再对局部" aria-label="Permalink to &quot;先对地标、再对局部&quot;">​</a></h3><p>推理或长上下文前向时，查询 \\(q_t\\) 先对已有地标键 \\(\\{k^{(L)}_b\\}\\) 打分。分高的块被视为命中，再把那些块的原始 \\(K,V\\) 载入，做第二次局部 softmax。未命中的块既不进细算，也不必留在高速缓存里。可见集于是变成「全部地标 + 少数块的原文」，与 \\(n\\) 解耦，只与块数（粗路）和选中块数 × \\(\\ell\\)（细路）有关。</p> \\[b^\\star=\\mathrm{top}\\text{-}k\\left(\\frac{q_t^\\top k^{(L)}_b}{\\sqrt{d}}\\right),\\qquad y_t=\\mathrm{softmax}\\!\\left(\\frac{q_t K_{b^\\star}^\\top}{\\sqrt{d}}\\right)V_{b^\\star} \\]<p>上式把两阶段写成分开的 softmax。也可以用地标分数做门控：超过阈值才展开该块，使 \\(k\\) 随内容变，而不是固定配额。训练需要让地标键真能代理块内注意力质量，否则粗路点中的块细路用不上。</p>',14)),(t(),s(p,null,{default:n(()=>[d(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%BE%93%E5%85%A5%E5%88%87%E5%9D%97%22%5D%20--%3E%20B%5B%22%E6%AF%8F%E5%9D%97%E4%B8%80%E4%B8%AA%E5%9C%B0%E6%A0%87%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%9F%A5%E8%AF%A2%E5%85%88%E5%AF%B9%E5%9C%B0%E6%A0%87%E6%89%93%E5%88%86%22%5D%0A%20%20C%20--%3E%20D%5B%22%E9%80%89%E5%87%BA%E7%9B%B8%E5%85%B3%E5%9D%97%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%9D%97%E5%86%85%E5%8E%9F%E5%A7%8B%20token%20%E7%BB%86%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20E%20--%3E%20F%5B%22%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h3 id="训练图与随机访问" tabindex="-1">训练图与随机访问 <a class="header-anchor" href="#训练图与随机访问" aria-label="Permalink to &quot;训练图与随机访问&quot;">​</a></h3><p>若训练仍用满注意力、只在推理改成地标检索，分布会裂开。做法是让训练期的可见集已经分层：当前块局部边 + 过去块的地标边，必要时再对若干块做可微的软展开，使「凭地标跳进原文」成为网络的一部分。地标自己对块内做满注意力，梯度从后续查询经地标流回块内 token，代表才学得动。</p><p>与 Longformer 全局点不同：全局点是任务指定的少数中枢，地标是按块均匀铺开的目录，每一块都有入口。与 NSA 的压缩支路同类，但 Landmark 2023 的主场是「随机访问已有块」，不是三路融核；实现更接近在标准注意力上改掩码与两段式检索。<span class="marginnote">随机访问强调的是：远块不必按时间顺序扫过。目录分数高，就可以直接展开第 \\(b\\) 块，中间那些块可以不进细算。这和滑窗的平移窗口不是同一张图。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>地标能当目录，是因为 softmax 的质量可以先在块级再分配，再在块内再分配。粗路回答「哪一段可能有答案」，细路回答「段内哪一个键」。只要块长小于模型一层内的舒适跨度，块内尖峰能力仍在，拷贝与针测仍可能——失败会出在粗路漏块，而不是出在块内对准。</p><p>块长 \\(\\ell\\) 同时决定目录粒度与漏检代价。太长，一个地标要代表太多互不相关的句子，查询点中块之后仍要对很长一段做二次注意力，目录变钝。太短，地标数量接近 \\(n\\)，粗路自己又变成二次。\\(\\ell\\) 应落在「一层局部注意力已经够用、目录项数仍远小于 \\(n\\)」的区间。</p><p><span class="marginnote">两段 softmax 不是一次满注意力的恒等改写。粗路用一个键代替整块，等价于对块内键做了内容相关的池化。漏块不可逆：细路看不见的 token 权重精确为零。评测应单独报块召回，而不是只报最终损失。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>离散选块会漏。阈值或 top-\\(k\\) 太狠，答案所在块进不了细路，表现为突然的针测崩溃，而不是平滑掉点。太松，又走回近似满注意力。地标本身占上下文一个位置，块很多时目录扫描也有成本，极端长度仍要考虑对地标再分级。</p><p>不要把 Landmark 理解成「推理时对 KV 做聚类」。代表是训练出来的 token，权重已经按「后续只能先看见地标」这条约束补偿过。对已训好的满注意力模型事后插地标、不微调，目录没有语义。也不要和 <a href="/llm/mla">MLA</a> 混名：MLA 压的是每个 token 的秩，地标压的是序列维的块数。</p><p>取舍：需要任意位置的精确随机访问，地标或可学习块选择是对口工具；只需要最近窗口加指令前缀，滑窗更便宜。部署上，未选中块的 KV 可以下放到主机内存或丢掉，这才是「无限上下文」的工程含义——不是算力真的无限，而是细算只打在命中块上。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Landmark Attention 把序列切块，每块一个可学习地标；查询先对地标、再对命中块的原文。</li><li>地标是序列里的真实 token，经训练成为块的可寻址目录，不是事后均值。</li><li>可见集与长度解耦：粗路扫块数，细路只扫选中块。</li><li>两段 softmax 会漏块；应报块召回，不能只看语言建模损失。</li><li>训练可见集必须已分层，不能满注意力预训练、推理再改成地标检索。</li><li>压缩轴是序列块，不是头数或精度；与 MLA、H2O 不是同一件事。</li><li>出处：Mohtashami &amp; Jaggi, <em>Landmark Attention: Random-Access Infinite Context Length for Transformers</em>, 2023。对照 Beltagy et al., <em>Longformer</em>, 2020；DeepSeek-AI, <em>DeepSeek-V2</em>（MLA）, 2024。</li></ul>',13))])}const q=r(h,[["render",k]]);export{B as __pageData,q as default};
